local clientProvider = require(script.Parent.WuKongClientProvider)
local optionsProvider = require(script.Parent.Parent.WuKongOptionsProvider)

local function buildClientOptions()
	local options = optionsProvider.BuildDefaultOptions()
	options.IsClientDev = true
	return options
end

return function()
	beforeEach(function()
		require(game.ReplicatedStorage.Packages.c2l)
	end)
	afterEach(function() end)

	describe("wukong server provider options test", function()
		it("use client dev options", function()
			-- 默认options无法单独启动单元测试
			local options = buildClientOptions()
			local client = clientProvider.BuildWuKongClient(options)
			expect(client).to.be.ok()
			clientProvider.Dispose()
		end)

		it("GetWuKongClient test", function()
			-- 默认options无法单独启动单元测试
			local options = buildClientOptions()
			local client = clientProvider.BuildWuKongClient(options)
			expect(client).to.be.ok()
			local facade = client:GetFacade()
			expect(facade).to.be.ok()
			local rootContainer = facade:GetRootContainer()
			expect(rootContainer).to.be.ok()
			clientProvider.Dispose()
		end)
	end)
end
